    const fx=LF.create(id),effectId=lesson.exampleId||fx.effectId||EFFECT_EXAMPLES[0].id;loadExamplePreset(effectId,{openView:false,announce:false});if(fx.bundleFiles)loadBundle({name:fx.bundleName||`${id}.cfxb`,files:fx.bundleFiles});inspectPkbPayload({name:fx.name,path:fx.assetPath||'',data:fx.bytes.buffer.slice(fx.bytes.byteOffset,fx.bytes.byteOffset+fx.bytes.byteLength)});
