    state.pkbSubtab='edit';setView(openView?'pkb':'designer');if(openView)setPkbSubtab('edit',{announce:false});$('#effectsExampleDialog')?.close?.();if(announce)status(`Loaded lesson: ${lesson.title} · ${fx.name} + ${examplePresetById(effectId).title}`);return{lesson,fixture:fx,effect:examplePresetById(effectId)};
