  async function scanLocalPkbCorpus(){if(!PC?.scanEntries)throw new Error('PKB Corpus Scanner module is unavailable.');const r=await bridge().choosePkbCorpus?.();if(!r||r.canceled)return null;const entries=(r.files||[]).map(f=>corpusEntryFromPayload(f,'local')).filter(Boolean),corpus=PC.scanEntries(entries,{name:'Local PKB Corpus',source:'local',previousRegistry:state.pkbStructureRegistry});setPkbCorpus(corpus);status(`PKB corpus: ${corpus.totalFiles} local file(s) · ${corpus.registry?.counts?.probable||0} probable evidence record(s).`);return corpus;}
