  function effectsHelpSection(target){
    const section=target?.closest?.('.effects-research-section,.effects-card,.effects-real-curve-editor,.effects-real-curve-discovery,.effects-real-curve-structure,.effects-curve-tree-v7,.effects-branch-author-v8,.effects-struct-session-v9,.effects-curve-baker,.effects-atlas-editor');
    const heading=section?.querySelector?.('.effects-research-head strong,.effects-card-head strong,.effects-real-curve-head strong,.effects-card-subhead strong')?.textContent||'Effects Lab';
    return String(heading).replace(/^\?\s*/,'').replace(/\s+/g,' ').trim();
  }
  function effectsHelpCopy(target){
    const control=target?.querySelector?.('input,select,textarea'),id=control?.id||target?.id||'';if(id&&EFFECTS_HELP_BY_ID[id])return EFFECTS_HELP_BY_ID[id];
    const title=String(target?.dataset?.helpTitle||target?.textContent||'').replace(/^\?\s*/,'').trim(),key=title.toLowerCase().replace(/\s+/g,' '),tab=target?.closest?.('.effects-tab');
    if(id&&control&&!EFFECTS_HELP_BY_ID[id]){const section=effectsHelpSection(target);return `${title||'This value'} is a control in ${section}. Change it to update that section's draft or selection; PKB bytes are written only by an explicit preview/save action after the required mapping or structure is confirmed.`;}
    if(tab){const view=tab.dataset.effectsView||'',copy={designer:'Build the effect visually: project/layer/object settings, Live Effect preview, motion, procedural color, and procedural shapes.',cfx:'File and backend workflow only. Open/save projects, import/export CFX, configure the backend, and build/decompile PKB data here.',pkb:'Advanced PKB editing and research area for confirmed fields, curves, structural branches, validation, and safe binary operations.',graph:'Visualize and edit layer/event/native-node relationships so you can see how the effect flows from one node to another.',samplers:'Edit Curve, Shape, turbulence, and other sampled data sources that feed values into layers and renderers.',renderers:'Edit the drawable effect components: Billboard, Ribbon, Light, or Mesh blocks, textures, blend, atlas, and draw order.',code:'Edit the raw CFX bundle files with syntax highlighting and cross-file validation. Hard errors block Apply and Build.'}[view];if(copy)return copy;}
    if(target?.closest?.('.effects-card-head')&&key==='samplers')return 'Sampler editor for Curve, Shape, turbulence, and other sampled blocks. Selecting a sampler opens its source and curve preview on the right.';
    if(target?.closest?.('.effects-card-head')&&key==='renderers')return 'Renderer editor for Billboard, Ribbon, Light, and Mesh blocks. Selecting a renderer opens its material/source and related atlas controls.';
    if(EFFECTS_HELP_HEADINGS[key])return EFFECTS_HELP_HEADINGS[key];
    if(/sample/.test(key))return 'Controls how densely the current curve, shape, or mathematical source is evaluated. More samples preserve more detail but increase preview/bake work and can produce more keys.';
    if(/alpha|opacity/.test(key))return 'Controls transparency. Lower alpha makes the result more transparent; over-life alpha curves are commonly used for fade-in and fade-out.';
    if(/size|scale/.test(key))return 'Controls visual size or a size multiplier. Values above 1 enlarge the result; values below 1 shrink it.';
    if(/speed|velocity/.test(key))return 'Controls motion speed or one velocity component. Velocity-over-life curves can accelerate, decelerate, or redirect particles during their lifetime.';
    if(/emission|spawn/.test(key))return 'Controls how many particles or objects are created over time. Higher emission increases density and usually increases runtime cost.';
    if(/life|duration/.test(key))return 'Controls how long the selected object, particle, layer, or effect state remains active before ending.';
    if(/color|team color/.test(key))return 'Controls a color input used by the current renderer or preview. Color curves/modulation can change RGB or alpha over time.';
    if(/texture|diffuse/.test(key))return 'Selects the image sampled by the renderer. Warcraft paths come from CASC/CDN; local files are used for external preview/editing.';
    if(/blend/.test(key))return 'Controls how this renderer is composited with the scene and other transparent layers, changing whether it brightens, fades, multiplies, or screens the background.';
    if(/channel/.test(key))return 'Selects the specific property/component affected by the current operation, such as Size, Alpha, Velocity X/Y/Z, or Color R/G/B.';
    if(/interpolation/.test(key))return 'Controls how values between curve keys are evaluated: Linear blends directly, Step holds a value until the next key, and Hermite uses tangents for smooth shaped transitions.';
    if(/gravity/.test(key))return 'Controls the mapped emitter gravity scalar. Changing it alters how strongly particles accelerate along the effect’s gravity direction during their lifetime.';
    if(/drag/.test(key))return 'Controls motion damping/resistance. Higher drag removes velocity faster, making particles slow down sooner after they are emitted.';
    if(/spread/.test(key))return 'Controls how widely emitted particles diverge from their initial direction. Higher spread produces a broader cone or more randomized distribution.';
    if(/rotation/.test(key))return 'Controls renderer rotation. It changes the orientation of the mapped particle or renderer element without changing its position.';
    if(/tangent/.test(key))return 'Controls a Hermite curve tangent at the selected key. In Tangent shapes the curve as it enters the key; Out Tangent shapes the curve as it leaves the key.';
    if(/time|lifetime position|life position/.test(key))return 'Normalized position of a curve key over particle life: 0 is birth and 1 is death. Moving it changes when the neighboring values are reached.';
    if(/value/.test(key))return 'Numeric value stored at the selected curve key or mapped field. Its meaning depends on the active channel, such as Size, Alpha, Velocity, or Color.';
    if(/record/.test(key))return 'Selects one decoded PKB record so edits or analysis stay scoped to that exact structure instead of similarly named fields elsewhere in the file.';
    if(/array/.test(key))return 'Selects one decoded PKB array participating in the current structural transaction. Array base/count/stride evidence must be confirmed before mutation is allowed.';
    if(/alignment/.test(key))return 'Sets the byte boundary used when appending new PKB data. The writer rounds new block offsets up to this alignment before calculating confirmed pointer updates.';
    if(/index/.test(key))return 'Selects the member position inside the current confirmed array or structural collection.';
    const section=effectsHelpSection(target);
    return `${title||'This control'} belongs to ${section}. It changes only the value represented by this control; binary PKB writing remains blocked unless the required field or structure is CONFIRMED.`;
  }
  function effectsHelpTitle(target){let raw=target?.dataset?.helpTitle||'';if(!raw&&target?.tagName==='LABEL'){const direct=[...target.childNodes].find(n=>n.nodeType===Node.TEXT_NODE&&String(n.textContent||'').trim());raw=direct?direct.textContent:([...target.children].find(x=>x.tagName==='SPAN')?.textContent||'');}if(!raw)raw=target?.textContent||'Help';return String(raw).replace(/^\?\s*/,'').replace(/\s+/g,' ').trim().slice(0,90)||'Help';}
